head.script:
scwin.screenId = "jldfil10609";

///////// 1. 변수 및 선언 영역 /////////

scwin.disclsAcptTpCd = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_submit();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil10609.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_ViewManualKeyWord_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ViewManualKeyWord_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ViewManualKeyWord_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_ViewManualKeyWord(0200000020)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil10609.btn_ViewManualKeyWord_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_resultVo_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_resultVo_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultVo');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_resultVo'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["disclsTitle"] === 'Voluntary Disclosure') { if (typeof scwin.disclosurePreview === 'function') { await scwin.disclosurePreview(r["applNo"], r["docNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.disclosurePreview (열 ())'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.disclosurePreview'); } return; }
        if (typeof scwin.disclosurePreview === 'function') { await scwin.disclosurePreview(r["applNo"], r["docNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.disclosurePreview (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.disclosurePreview'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultVo.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_submit_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_submit_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_submit_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.submit()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil10609.btn_submit_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_goList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goList_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.goList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil10609.btn_goList_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_attachPreview
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_attachPreview = async function () {
    try { return await $c.data.downFile("/submission/attachFileDown.do?method=searchAttachFile", "", ($c.util.getComponent("dma_attachPreviewReq") ? $c.util.getComponent("dma_attachPreviewReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_fn_submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_submit = async function () {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: "/esg/writeESGSubmitInfoForm.do?method=esgEngSubmitDocument",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil10609.tx_fn_submit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goList = function () {
    /* sdd-asis-lifecycle:begin fn_goList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil10602/jldfil10602.xml');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disclosurePreview
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo disclsDocNo
 * @returns
 * @hidden N
*/
scwin.disclosurePreview = async function (applNo, disclsDocNo) {
    /* sdd-asis-lifecycle:begin fn_disclosurePreview — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert("해당 공시는 미리보기가 제공되지 않습니다. 제출 후 KIND 조회시스템을 통해 확인해주세요.");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.attachPreview
 * @author Inswave
 * @date 2026. 09. 29
 * @param docNo attachSeq
 * @returns
 * @hidden N
*/
scwin.attachPreview = async function (docNo, attachSeq) {
    /* sdd-asis-lifecycle:begin fn_attachPreview — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert("해당 공시는 미리보기가 제공되지 않습니다. 제출 후 KIND 조회시스템을 통해 확인해주세요.");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.submit = async function () {
    /* sdd-asis-lifecycle:begin fn_submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.submitFrm || { elements: [] }).action = '/esg/writeESGSubmitInfoForm.do?method=esgEngSubmitDocument';
    await scwin.tx_fn_submit();
    /* sdd-asis-lifecycle:end */
};
